// Foto do perfil embutida como data URI. Os browsers não bloqueiam a leitura
// dos píxeis de imagens data:, por isso o efeito de meio-tom funciona também
// ao abrir o site localmente (file://). Gerado a partir de portrait.jpg:
// se mudares a foto, este ficheiro tem de ser gerado de novo.
window.PORTRAIT_DATA = 'data:image/jpeg;base64,';
